```tsx
// CheckoutPage.tsx
import React, { useMemo, useState } from 'react';
import { CartItem, CheckoutPageProps, DeliveryAddress } from './CheckoutPage.types';
import './CheckoutPage.css';

const SHIPPING_FEE = 5.99;

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: '',
  email: '',
  phone: '',
  street: '',
  city: '',
  postalCode: '',
  country: '',
};

type AddressErrors = Partial<Record<keyof DeliveryAddress, string>>;

const EMAIL_REGEX = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function formatCurrency(value: number): string {
  return `$${value.toFixed(2)}`;
}

function validateAddress(address: DeliveryAddress): AddressErrors {
  const errors: AddressErrors = {};

  if (!address.fullName.trim()) errors.fullName = 'Full name is required.';
  if (!address.email.trim()) {
    errors.email = 'Email is required.';
  } else if (!EMAIL_REGEX.test(address.email.trim())) {
    errors.email = 'Enter a valid email address.';
  }
  if (!address.phone.trim()) errors.phone = 'Phone number is required.';
  if (!address.street.trim()) errors.street = 'Street address is required.';
  if (!address.city.trim()) errors.city = 'City is required.';
  if (!address.postalCode.trim()) {
    errors.postalCode = 'Postal code is required.';
  } else if (!/^[A-Za-z0-9\s-]{3,10}$/.test(address.postalCode.trim())) {
    errors.postalCode = 'Enter a valid postal code.';
  }
  if (!address.country.trim()) errors.country = 'Country is required.';

  return errors;
}

function CartItemRow({ item }: { item: CartItem }) {
  const lineTotal = item.price * item.quantity;
  return (
    <li className="cart-item">
      <div className="cart-item__image-wrap">
        {item.imageUrl ? (
          <img className="cart-item__image" src={item.imageUrl} alt={item.name} />
        ) : (
          <div className="cart-item__image cart-item__image--placeholder" aria-hidden="true" />
        )}
      </div>
      <div className="cart-item__details">
        <p className="cart-item__name">{item.name}</p>
        <p className="cart-item__meta">
          {formatCurrency(item.price)} &times; {item.quantity}
        </p>
      </div>
      <div className="cart-item__total">{formatCurrency(lineTotal)}</div>
    </li>
  );
}

export default function CheckoutPage({
  items,
  onBackToCart,
  onPay,
  isProcessingPayment = false,
}: CheckoutPageProps) {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [errors, setErrors] = useState<AddressErrors>({});
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});

  const subtotal = useMemo(
    () => items.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [items]
  );
  const shipping = items.length > 0 ? SHIPPING_FEE : 0;
  const total = subtotal + shipping;
  const isCartEmpty = items.length === 0;

  function handleFieldChange(field: keyof DeliveryAddress, value: string) {
    setAddress((prev) => ({ ...prev, [field]: value }));
  }

  function handleFieldBlur(field: keyof DeliveryAddress) {
    setTouched((prev) => ({ ...prev, [field]: true }));
    setErrors(validateAddress(address));
  }

  function handleSubmit(event: React.FormEvent) {
    event.preventDefault();
    const validationErrors = validateAddress(address);
    setErrors(validationErrors);
    setTouched({
      fullName: true,
      email: true,
      phone: true,
      street: true,
      city: true,
      postalCode: true,
      country: true,
    });

    if (Object.keys(validationErrors).length === 0 && !isCartEmpty) {
      onPay(address);
    }
  }

  function renderField(
    field: keyof DeliveryAddress,
    label: string,
    options: { type?: string; placeholder?: string; autoComplete?: string } = {}
  ) {
    const hasError = Boolean(touched[field] && errors[field]);
    return (
      <div className="form-field">
        <label className="form-field__label" htmlFor={field}>
          {label}
        </label>
        <input
          id={field}
          name={field}
          type={options.type ?? 'text'}
          className={`form-field__input ${hasError ? 'form-field__input--error' : ''}`}
          placeholder={options.placeholder}
          autoComplete={options.autoComplete}
          value={address[field]}
          onChange={(e) => handleFieldChange(field, e.target.value)}
          onBlur={() => handleFieldBlur(field)}
          aria-invalid={hasError}
          aria-describedby={hasError ? `${field}-error` : undefined}
        />
        {hasError && (
          <p className="form-field__error" id={`${field}-error`}>
            {errors[field]}
          </p>
        )}
      </div>
    );
  }

  return (
    <div className="checkout-page">
      <div className="checkout-page__header">
        <button type="button" className="back-link" onClick={onBackToCart}>
          &larr; Back to cart
        </button>
        <h1 className="checkout-page__title">Checkout</h1>
      </div>

      <div className="checkout-page__layout">
        <section className="checkout-section" aria-labelledby="order-summary-heading">
          <h2 id="order-summary-heading" className="checkout-section__heading">
            Order Summary
          </h2>

          {isCartEmpty ? (
            <p className="empty-cart-message">Your cart is empty.</p>
          ) : (
            <ul className="cart-item-list">
              {items.map((item) => (
                <CartItemRow key={item.id} item={item} />
              ))}
            </ul>
          )}

          <div className="order-totals">
            <div className="order-totals__row">
              <span>Subtotal</span>
              <span>{formatCurrency(subtotal)}</span>
            </div>
            <div className="order-totals__row">
              <span>Shipping</span>
              <span>{formatCurrency(shipping)}</span>
            </div>
            <div className="order-totals__row order-totals__row--total">
              <span>Total</span>
              <span>{formatCurrency(total)}</span>
            </div>
          </div>
        </section>

        <section className="checkout-section" aria-labelledby="delivery-address-heading">
          <h2 id="delivery-address-heading" className="checkout-section__heading">
            Delivery Address
          </h2>

          <form className="address-form" onSubmit={handleSubmit} noValidate>
            {renderField('fullName', 'Full name', {
              placeholder: 'Jane Doe',
              autoComplete: 'name',
            })}
            {renderField('email', 'Email', {
              type: 'email',
              placeholder: 'jane@example.com',
              autoComplete: 'email',
            })}
            {renderField('phone', 'Phone number', {
              type: 'tel',
              placeholder: '+1 555 123 4567',
              autoComplete: 'tel',
            })}
            {renderField('street', 'Street address', {
              placeholder: '123 Main St, Apt 4',
              autoComplete: 'street-address',
            })}

            <div className="form-field-row">
              {renderField('city', 'City', { autoComplete: 'address-level2' })}
              {renderField('postalCode', 'Postal code', {
                autoComplete: 'postal-code',
              })}
            </div>

            {renderField('country', 'Country', { autoComplete: 'country-name' })}

            <button
              type="submit"
              className="pay-button"
              disabled={isCartEmpty || isProcessingPayment}
            >
              {isProcessingPayment ? 'Processing…' : `Pay ${formatCurrency(total)}`}
            </button>
          </form>
        </section>
      </div>
    </div>
  );
}
```

