// App.tsx (example usage)
import CheckoutPage from './CheckoutPage';
import { CartItem, DeliveryAddress } from './CheckoutPage.types';

const sampleItems: CartItem[] = [
  { id: '1', name: 'Wireless Headphones', price: 79.99, quantity: 1 },
  { id: '2', name: 'USB-C Cable', price: 9.99, quantity: 2 },
];

export default function App() {
  function handleBackToCart() {
    console.log('Navigate back to cart');
  }

  function handlePay(address: DeliveryAddress) {
    console.log('Processing payment for address:', address);
  }

  return (
    <CheckoutPage
      items={sampleItems}
      onBackToCart={handleBackToCart}
      onPay={handlePay}
    />
  );
}
```

Notes:
- Validation covers required fields, email format, and a loose postal-code pattern; errors show on blur and on submit.
- The Pay button is disabled when the cart is empty or a payment is already processing (`isProcessingPayment` prop).
- Layout is a responsive two-column grid that stacks on screens ≤720px.
